int firealarm_infer(const float input[INPUT_C * INPUT_H * INPUT_W], float output[NUM_CLASSES])
{
    static int8_t in_q[INPUT_C * INPUT_H * INPUT_W];
    static int8_t buf1[16 * INPUT_H * INPUT_W];
    static int8_t buf2[16 * (INPUT_H / 2) * (INPUT_W / 2)];
    static int8_t buf3[32 * (INPUT_H / 2) * (INPUT_W / 2)];
    static int8_t buf4[32 * (INPUT_H / 4) * (INPUT_W / 4)];
    static int8_t buf5[64 * (INPUT_H / 4) * (INPUT_W / 4)];
    static int8_t buf6[64 * (INPUT_H / 8) * (INPUT_W / 8)];
    static int8_t gap[64];
    static int8_t fc1[64];
    static int8_t logits_q[NUM_CLASSES];

    for (int i = 0; i < INPUT_C * INPUT_H * INPUT_W; ++i) {
        in_q[i] = clamp_int8(round_to_int32(input[i] / INPUT_INPUT_SCALE));
    }

    conv2d_3x3_same_int8(in_q, INPUT_C, INPUT_H, INPUT_W, conv1_w, conv1_w_scale, conv1_b, INPUT_INPUT_SCALE, CONV1_ACT_SCALE, 16, buf1);
    for (int i = 0; i < (int)(sizeof(buf1)/sizeof(buf1[0])); ++i) buf1[i] = buf1[i] > 0 ? buf1[i] : 0;
    maxpool2d_2x2_stride2_int8(buf1, 16, INPUT_H, INPUT_W, buf2);

    conv2d_3x3_same_int8(buf2, 16, INPUT_H / 2, INPUT_W / 2, conv2_w, conv2_w_scale, conv2_b, CONV1_ACT_SCALE, CONV2_ACT_SCALE, 32, buf3);
    for (int i = 0; i < (int)(sizeof(buf3)/sizeof(buf3[0])); ++i) buf3[i] = buf3[i] > 0 ? buf3[i] : 0;
    maxpool2d_2x2_stride2_int8(buf3, 32, INPUT_H / 2, INPUT_W / 2, buf4);

    conv2d_3x3_same_int8(buf4, 32, INPUT_H / 4, INPUT_W / 4, conv3_w, conv3_w_scale, conv3_b, CONV2_ACT_SCALE, CONV3_ACT_SCALE, 64, buf5);
    for (int i = 0; i < (int)(sizeof(buf5)/sizeof(buf5[0])); ++i) buf5[i] = buf5[i] > 0 ? buf5[i] : 0;
    maxpool2d_2x2_stride2_int8(buf5, 64, INPUT_H / 4, INPUT_W / 4, buf6);

    global_avg_pool_int8(buf6, 64, INPUT_H / 8, INPUT_W / 8, CONV3_ACT_SCALE, CONV3_ACT_SCALE, gap);
    linear_layer_int8(gap, 64, fc1_w, fc1_w_scale, fc1_b, CONV3_ACT_SCALE, FC1_ACT_SCALE, 64, fc1);
    for (int i = 0; i < 64; ++i) fc1[i] = fc1[i] > 0 ? fc1[i] : 0;
    linear_layer_int8(fc1, 64, fc2_w, fc2_w_scale, fc2_b, FC1_ACT_SCALE, LOGIT_SCALE, NUM_CLASSES, logits_q);

    for (int i = 0; i < NUM_CLASSES; ++i) {
        output[i] = (float)logits_q[i] * LOGIT_SCALE;
    }
    return argmax3(output);
}

void firealarm_predict(const float input[INPUT_C * INPUT_H * INPUT_W], firealarm_prediction_t *prediction)
{
    float logits[NUM_CLASSES];
    if (prediction == NULL) {
        return;
    }
    prediction->class_id = firealarm_infer(input, logits);
    for (int i = 0; i < NUM_CLASSES; ++i) {
        prediction->logits[i] = logits[i];
    }
    softmax3(logits, prediction->probabilities);
    prediction->confidence = prediction->probabilities[prediction->class_id];
}

const char* firealarm_class_name(int class_id)
{
    switch (class_id) {
        case 0: return "normal";
        case 1: return "warning";
        case 2: return "fire";
        default: return "unknown";
    }
}

